macro.dbt_sqlserver.sqlserver__apply_den.macro_sql:
{% macro sqlserver__apply_denies(relation, deny_config, should_revoke=True) %}
    {#-- If deny_config is {} or None, this is a no-op (mirrors apply_grants). --#}
    {% if not deny_config %}
        {{ return(none) }}
    {% endif %}

    {#-- Reconcile against live state. On a fresh build there is nothing to
         revoke, so skip the round-trip and treat every configured deny as an
         add — exactly apply_grants' should_revoke shortcut. --#}
    {% if should_revoke %}
        {% set existing_denies = run_query(get_show_deny_sql(relation)) %}
    {% else %}
        {% set existing_denies = none %}
    {% endif %}

    {% set changes = adapter.deny_changes(existing_denies, deny_config) %}

    {#-- A DENY to a non-existent principal errors, and the principal set differs
         across dev / CI / prod, so warn-and-skip rather than fail — one config
         then runs unchanged everywhere. Revoked denies reference principals that
         necessarily still exist. --#}
    {% set existing_principals = sqlserver__get_existing_principals() %}

    {#-- Revoke first, then deny (order is immaterial — a (privilege, principal)
         pair is only ever on one side of the diff). --#}
    {% set statements = [] %}
    {% for privilege, principal in changes['revokes'] %}
        {% do statements.append(
            "revoke " ~ privilege ~ " on " ~ relation ~ " from ["
            ~ (principal | replace(']', ']]')) ~ "]") %}
    {% endfor %}
    {% for privilege, principal in changes['denies'] %}
        {% if (principal | trim | lower) in existing_principals %}
            {% do statements.append(
                "deny " ~ privilege ~ " on " ~ relation ~ " to ["
                ~ (principal | replace(']', ']]')) ~ "]") %}
        {% else %}
            {% do exceptions.warn("apply_denies on " ~ relation ~ ": database principal '"
                ~ principal ~ "' does not exist; skipping DENY " ~ privilege ~ ". "
                ~ "Create the principal or remove it from `denies`.") %}
        {% endif %}
    {% endfor %}

    {% if statements %}
        {% do run_query(statements | join(";\n")) %}
        {% do log("Applied " ~ statements | length ~ " deny change(s) on "
                  ~ relation, info=true) %}
    {% else %}
        {% do log("On " ~ relation ~ ": all denies are in place, no changes needed.") %}
    {% endif %}
{% endmacro %}

macro.dbt_sqlserver.sqlserver__apply_gra.macro_sql:
{% macro sqlserver__apply_grants(relation, grant_config, should_revoke=True) %}
    {#-- If grant_config is {} or None, this is a no-op --#}
    {% if grant_config %}
        {% if should_revoke %}
            {#-- We think previous grants may have carried over --#}
            {#-- Show current grants and calculate diffs --#}
            {% set current_grants_table = run_query(get_show_grant_sql(relation)) %}
            {% set current_grants_dict = adapter.standardize_grants_dict(current_grants_table) %}
            {% set needs_granting = diff_of_two_dicts(grant_config, current_grants_dict) %}
            {% set needs_revoking = diff_of_two_dicts(current_grants_dict, grant_config) %}
            {% if not (needs_granting or needs_revoking) %}
                {{ log('On ' ~ relation ~': All grants are in place, no revocation or granting needed.')}}
            {% endif %}
        {% else %}
            {#-- We don't think there's any chance of previous grants having carried over. --#}
            {#-- Jump straight to granting what the user has configured. --#}
            {% set needs_revoking = {} %}
            {% set needs_granting = grant_config %}
        {% endif %}
        {% if needs_granting or needs_revoking %}
            {% set revoke_statement_list = get_dcl_statement_list(relation, needs_revoking, get_revoke_sql) %}

            {% if config.get('auto_provision_aad_principals', False) %}
                {% set provision_statement_list = get_dcl_statement_list(relation, needs_granting, get_provision_sql) %}
            {% else %}
                {% set provision_statement_list = [] %}
            {% endif %}

            {% set grant_statement_list = get_dcl_statement_list(relation, needs_granting, get_grant_sql) %}
            {% set dcl_statement_list = revoke_statement_list + provision_statement_list + grant_statement_list %}
            {% if dcl_statement_list %}
                {{ call_dcl_statements(dcl_statement_list) }}
            {% endif %}
        {% endif %}
    {% endif %}
{% endmacro %}

